#[derive(Serialize, Deserialize)]
struct Hop { name: String, at_ms: u64 }

fn headers_with_hop(existing: Option<&[u8]>, me: &str) -> OwnedHeaders {
    let mut hops: Vec<Hop> = existing
        .and_then(|b| serde_json::from_slice(b).ok())
        .unwrap_or_default();
    hops.push(Hop { name: me.into(), at_ms: now_ms() });
    OwnedHeaders::new().insert(Header { key: "history", value: Some(&serde_json::to_vec(&hops).unwrap()) })
}
